ui.defaultValue:
query ($start: Time!, $end: Time!) {
  viewer {
    zones(limit: 1) {
      httpRequests1hGroups(
        limit: 1000
        filter: { datetime_geq: $start, datetime_leq: $end }
        orderBy: [datetime_ASC]
      ) {
        dimensions {
          datetime
        }
        sum {
          requests
          bytes
          cachedRequests
          threats
        }
        uniq {
          uniques
        }
      }
    }
  }
}
